  "core_ideas": [
    {
      "title": "Two Systems of Thinking",
      "description": "Kahneman introduces two systems of thinking: System 1 and System 2. System 1 is fast, intuitive, and automatic. It operates effortlessly and is responsible for quick judgments and gut reactions. System 2 is slow, deliberate, and analytical. It handles complex reasoning and conscious decision-making."
    },
    {
      "title": "Heuristics and Biases",
      "description": "People often rely on mental shortcuts (heuristics) to make decisions quickly. While these can be efficient, they can also lead to systematic errors or biases. Examples include the availability heuristic (judging the likelihood of events based on how easily examples come to mind) and the anchoring effect (relying too heavily on the first piece of information encountered)."
    },
    {
      "title": "Framing Effects",
      "description": "The way information is presented (framed) significantly influences decisions. People react differently to the same information when it is framed in terms of potential gains versus losses."
    },
    {
      "title": "Prospect Theory",
      "description": "Kahneman and Tversky developed Prospect Theory, which explains how people evaluate potential gains and losses. It shows that people are generally more sensitive to losses than to equivalent gains (loss aversion) and that their decisions are influenced more by perceived changes in wealth than by actual wealth."
    },
    {
      "title": "Narrative Fallacy",
      "description": "Humans tend to construct simple and coherent stories to explain complex events, often ignoring the role of chance. This can lead to overconfidence in our understanding of the world and the decisions we make."
    },
    {
      "title": "The Role of Emotion",
      "description": "Emotions play a significant role in decision-making. Kahneman highlights how emotional experiences can strongly influence our memories and future choices, often more than objective facts."
    },
    {
      "title": "Improving Decision-Making",
      "description": "Kahneman suggests that being aware of our cognitive biases can help us make better decisions. Encouraging a culture of doubt and systematically questioning intuitions can reduce the impact of biases. In some cases, replacing human judgment with algorithms can lead to more accurate predictions."
    }
  ]
}
