  "CAP_Theorem": {
    "Explanation": "The CAP theorem, also known as Brewer's theorem, states that in a distributed data store, it is impossible to simultaneously guarantee all three of the following: Consistency (every read receives the most recent write or an error), Availability (every request receives a response, without guarantee that it contains the most recent write), and Partition Tolerance (the system continues to operate despite arbitrary partitioning due to network failures).",
    "Examples": {
      "Consistency_and_Availability": {
        "System": "Relational Databases (e.g., MySQL with synchronous replication)",
        "Tradeoff": "These systems prioritize Consistency and Availability, but they are not Partition Tolerant. If a network partition occurs, they may become unavailable to maintain consistency."
      },
      "Availability_and_Partition_Tolerance": {
        "System": "Dynamo-style systems (e.g., Amazon DynamoDB)",
        "Tradeoff": "These systems prioritize Availability and Partition Tolerance. They allow reads and writes to proceed even during a network partition, but this can lead to inconsistencies that need to be resolved later."
      },
      "Consistency_and_Partition_Tolerance": {
        "System": "ZooKeeper",
        "Tradeoff": "ZooKeeper prioritizes Consistency and Partition Tolerance. It ensures that all nodes agree on the state of the system, even in the presence of network partitions, but this can lead to reduced availability if a majority of nodes cannot communicate."
      }
    }
  }
}
