            Assert.IsTrue(EmailValidator.IsValidEmail("user.name+tag@sub.domain.org"));
        }

        [TestMethod]
        public void TestInvalidEmails()
        {
            Assert.IsFalse(EmailValidator.IsValidEmail("invalid-email@"));
            Assert.IsFalse(EmailValidator.IsValidEmail("user@domain."));
            Assert.IsFalse(EmailValidator.IsValidEmail("user@domain.c"));
            Assert.IsFalse(EmailValidator.IsValidEmail("user@domain..com"));
            Assert.IsFalse(EmailValidator.IsValidEmail("user@"));
        }
    }

    public static class EmailValidator
    {
        private static readonly Regex EmailRegex = new Regex(
            @"^[^@\s]+@[^@\s]+\.[^@\s]+$",
            RegexOptions.Compiled);

        public static bool IsValidEmail(string email)
        {
            if (string.IsNullOrWhiteSpace(email))
            {
                return false;
            }

            return EmailRegex.IsMatch(email);
        }
    }
}"

"function mergeTwoLists(l1, l2) {
    // Create a dummy node to act as the starting point of the merged list
    let dummy = new ListNode(0);
    // Tail will be used to build the new list
    let tail = dummy;

    // Traverse both lists
    while (l1 !== null && l2 !== null) {
        if (l1.val <= l2.val) {
            tail.next = l1;
            l1 = l1.next;
        } else {
            tail.next = l2;
            l2 = l2.next;
        }
        tail = tail.next;
    }

    // Attach the remaining elements of l1 or l2
    tail.next = l1 !== null ? l1 : l2;

    // The merged list is next to the dummy node
    return dummy.next;
}

// Definition for singly-linked list
class ListNode {
    constructor(val, next = null) {
        this.val = val;
        this.next = next;
    }
}

