"package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
)

// Function to read a JSON file and print top-level keys
func printTopLevelKeys(filename string) error {
	// Read the file
	data, err := ioutil.ReadFile(filename)
	if err != nil {
		return err
	}

	// Parse the JSON data
	var obj map[string]interface{}
	if err := json.Unmarshal(data, &obj); err != nil {
		return err
	}

	// Print each top-level key
	for key := range obj {
		fmt.Println(key)
	}

	return nil
}

func main() {
	// Check if the filename is provided as a command-line argument
	if len(os.Args) < 2 {
		fmt.Println(\"Usage: go run main.go <filename>\")
		os.Exit(1)
	}

	filename := os.Args[1]
	if err := printTopLevelKeys(filename); err != nil {
		fmt.Fprintf(os.Stderr, \"Error: %v\\n\", err)
		os.Exit(1)
	}
}"
